package edu.tiet.scms.dashboard.components;

import com.fasterxml.jackson.databind.JsonNode;
import com.vaadin.flow.component.Html;
import com.vaadin.flow.component.details.Details;
import com.vaadin.flow.component.grid.Grid;
import com.vaadin.flow.component.html.*;
import java.util.*;

/** Free SVG charts generated by Java. No commercial chart component or custom JS. */
public class DataChart extends Div {
  public DataChart(String title, JsonNode data, String xKey, List<String> series, boolean line) {
    addClassName("card");
    add(new H2(title));
    List<JsonNode> rows = new ArrayList<>();
    data.forEach(rows::add);
    if (rows.isEmpty()) {
      add(new Paragraph("No activity in this period."));
      return;
    }
    double max =
        rows.stream()
            .flatMapToDouble(r -> series.stream().mapToDouble(k -> r.path(k).asDouble()))
            .max()
            .orElse(1);
    max = Math.max(1, max);
    String[] colors = {"#3b82f6", "#10b981", "#6b7280"};
    StringBuilder svg =
        new StringBuilder(
            "<div><svg viewBox=\"0 0 640 280\" role=\"img\" aria-label=\""
                + escape(title)
                + "\" xmlns=\"http://www.w3.org/2000/svg\">");
    for (int tick = 0; tick <= 4; tick++) {
      double y = 230 - tick * 50;
      svg.append("<path d=\"M48 ")
          .append(y)
          .append(" H625\" stroke=\"#e5e7eb\"/><text x=\"4\" y=\"")
          .append(y + 4)
          .append("\" fill=\"#6b7280\" font-size=\"12\">")
          .append(String.format(Locale.ROOT, max < 4 ? "%.1f" : "%.0f", max * tick / 4))
          .append("</text>");
    }
    double step = 560.0 / Math.max(rows.size(), 1);
    for (int s = 0; s < series.size(); s++) {
      String key = series.get(s), color = colors[s % colors.length];
      StringBuilder points = new StringBuilder();
      for (int i = 0; i < rows.size(); i++) {
        double x = 50 + step * (i + 0.5),
            height = rows.get(i).path(key).asDouble() / max * 200,
            y = 230 - height;
        if (line) {
          points.append(x).append(',').append(y).append(' ');
          svg.append("<circle cx=\"")
              .append(x)
              .append("\" cy=\"")
              .append(y)
              .append("\" r=\"3\" fill=\"")
              .append(color)
              .append("\"><title>")
              .append(escape(Ui.value(rows.get(i), xKey)))
              .append(" | ")
              .append(escape(Ui.label(key)))
              .append(": ")
              .append(rows.get(i).path(key).asDouble())
              .append("</title></circle>");
        } else
          svg.append("<rect x=\"")
              .append(x - step * .3)
              .append("\" y=\"")
              .append(y)
              .append("\" width=\"")
              .append(step * .6)
              .append("\" height=\"")
              .append(height)
              .append("\" fill=\"")
              .append(color)
              .append("\"><title>")
              .append(escape(Ui.value(rows.get(i), xKey)))
              .append(": ")
              .append(rows.get(i).path(key).asDouble())
              .append("</title></rect>");
        if (i % Math.max(1, rows.size() / 7) == 0)
          svg.append("<text x=\"")
              .append(x)
              .append("\" y=\"250\" text-anchor=\"middle\" fill=\"#6b7280\" font-size=\"11\">")
              .append(escape(shortLabel(Ui.value(rows.get(i), xKey))))
              .append("</text>");
      }
      if (line)
        svg.append("<polyline fill=\"none\" stroke-width=\"2.5\" stroke=\"")
            .append(color)
            .append("\" points=\"")
            .append(points)
            .append("\"/>");
    }
    svg.append("</svg></div>");
    add(new Html(svg.toString()));
    Div legend = new Div();
    legend.addClassName("chart-legend");
    for (int i = 0; i < series.size(); i++) {
      Span l = new Span(Ui.label(series.get(i)));
      l.getStyle().set("color", colors[i % 3]);
      legend.add(l);
    }
    add(legend);
    Grid<JsonNode> table = new Grid<>();
    Set<String> keys = new LinkedHashSet<>();
    rows.forEach(r -> r.fieldNames().forEachRemaining(keys::add));
    for (String k : keys)
      table.addColumn(r -> Ui.value(r, k)).setHeader(Ui.label(k)).setAutoWidth(true);
    table.setItems(rows);
    table.setAllRowsVisible(true);
    add(new Details("View chart data", table));
  }

  private static String shortLabel(String text) {
    return text.length() > 12 ? text.substring(0, 11) + "…" : text;
  }

  public static String escape(String text) {
    return text.replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace("\"", "&quot;")
        .replace("'", "&#39;");
  }
}
